<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {api,state} from '../state';
import {readableLibraries,type LibraryRef,type ContentKind} from '../api/libraries';
import {categoryOptions,createCategoriesApi,loadCategoryTree,type Category,type CategoryAISettings,type CategoryPreview,type CategoryTask,type CategoryTaskStatus} from '../api/categories';
import {errorMessage} from '../api/errors';
const route=useRoute(),router=useRouter(),client=createCategoriesApi(api);
const libraries=ref<LibraryRef[]>([]),library=ref(typeof route.query.library==='string'?Number(route.query.library):0),kind=ref<ContentKind>(route.query.content_kind==='comic'?'comic':'book'),items=ref<Category[]>([]),deleted=ref(false),loading=ref(true),error=ref(''),message=ref(''),busy=ref(false);
const selectedLibrary=computed(()=>libraries.value.find(lib=>lib.id===library.value)),visibleLibraries=computed(()=>readableLibraries(libraries.value,kind.value)),canManage=computed(()=>!state.offline&&selectedLibrary.value?.can_manage===true),adminEligible=computed(()=>canManage.value&&state.user?.role==='admin');
const options=computed(()=>categoryOptions(items.value,library.value,kind.value,deleted.value).filter(c=>c.deleted===deleted.value));
const editor=ref<'create'|'edit'|null>(null),editSnapshot=ref<Category|null>(null),draft=ref({name:'',parent_id:null as number|null}),editError=ref(''),editConflict=ref(false),saving=ref(false),deleteTarget=ref<Category|null>(null);
const parentOptions=computed(()=>{const excluded=new Set<number>();if(editSnapshot.value){excluded.add(editSnapshot.value.id);for(let pass=0;pass<3;pass++)for(const c of items.value)if(c.parent_id!==null&&excluded.has(c.parent_id))excluded.add(c.id)}return categoryOptions(items.value,library.value,kind.value).filter(c=>c.depth<2&&!excluded.has(c.id))});
const settings=ref<CategoryAISettings|null>(null),settingsDraft=ref({ai_enabled:false,ai_mode:'review' as 'review'|'direct',auto_new:false}),settingsDirty=ref(false),settingsConflict=ref(false),aiError=ref(''),aiMessage=ref(''),aiBusy=ref(false),limit=ref(50),preview=ref<CategoryPreview|null>(null);
const canAdmin=computed(()=>adminEligible.value&&settings.value?.can_admin===true&&settings.value.library_id===library.value),canPreview=computed(()=>canAdmin.value&&settings.value?.ai_enabled&&settings.value?.configured&&!settingsDirty.value&&!settingsConflict.value&&limit.value>=1&&limit.value<=500);
const tasks=ref<CategoryTask[]>([]),taskTotal=ref(0),taskPage=ref(1),taskStatus=ref<CategoryTaskStatus|''>(''),taskCounts=ref<Partial<Record<CategoryTaskStatus,number>>>({}),taskSelected=ref<number[]>([]),taskLoading=ref(false),reviewConflicts=ref<{id:number;reason:string}[]>([]);
const taskLabels:Record<CategoryTaskStatus,string>={pending:'等待中',running:'识别中',review:'待审核',applied:'已应用',skipped:'已跳过',failed:'失败',rejected:'已拒绝',cancelled:'已取消'};
const reviewIDs=computed(()=>taskSelected.value.filter(id=>tasks.value.some(t=>t.id===id&&t.status==='review')).slice(0,100));
let closed=false,generation=0,categoryGeneration=0,taskGeneration=0,timer:ReturnType<typeof setTimeout>|undefined;
function assignmentPath(c:Category){return {path:kind.value==='comic'?'/comics':'/',query:{library:String(c.library_id),category:String(c.id)}}}
function openEditor(row?:Category){editSnapshot.value=row?{...row}:null;draft.value={name:row?.name??'',parent_id:row?.parent_id??null};editError.value='';editConflict.value=false;editor.value=row?'edit':'create'}
async function saveCategory(){if(!canManage.value||saving.value||editConflict.value||!draft.value.name.trim())return;const g=generation,lib=library.value;saving.value=true;editError.value='';
 try{const body={name:draft.value.name.trim(),parent_id:draft.value.parent_id};if(editSnapshot.value)await client.update(editSnapshot.value.id,{...body,revision:editSnapshot.value.revision});else await client.create({library_id:lib,...body});if(closed||g!==generation)return;editor.value=null;message.value='分类已保存';await loadCategories(g)}
 catch(e:any){if(!closed&&g===generation){editError.value=errorMessage(e);if([403,404,409].includes(e?.status))editConflict.value=true}}finally{if(!closed)saving.value=false}
}
async function loadCategories(g=generation){const cg=++categoryGeneration,lib=library.value,k=kind.value,showDeleted=deleted.value&&canManage.value;if(!lib){items.value=[];loading.value=false;return}loading.value=true;error.value='';try{const data=await loadCategoryTree(client,lib,k,showDeleted);if(!closed&&g===generation&&cg===categoryGeneration)items.value=data}catch(e){if(!closed&&g===generation&&cg===categoryGeneration)error.value=errorMessage(e)}finally{if(!closed&&g===generation&&cg===categoryGeneration)loading.value=false}}
async function treeAction(action:'defaults'|'remove'|'restore',row?:Category){if(!canManage.value||busy.value)return;const g=generation;busy.value=true;error.value='';try{if(action==='defaults')await client.defaults(library.value);else if(row&&action==='remove')await client.remove(row.id,row.revision);else if(row)await client.restore(row.id,row.revision);if(closed||g!==generation)return;deleteTarget.value=null;message.value=action==='restore'?'分类已恢复':action==='remove'?'分类及其活动子分类已删除':'推荐分类已初始化';await loadCategories(g)}catch(e){if(!closed&&g===generation)error.value=errorMessage(e)}finally{if(!closed)busy.value=false}}
function resetAI(){settings.value=null;settingsDraft.value={ai_enabled:false,ai_mode:'review',auto_new:false};settingsDirty.value=false;settingsConflict.value=false;preview.value=null;tasks.value=[];taskCounts.value={};taskTotal.value=0;taskLoading.value=false;taskPage.value=1;taskSelected.value=[];reviewConflicts.value=[];aiError.value='';aiMessage.value='';clearTimeout(timer);taskGeneration++}
async function loadSettings(g=generation,preserve=false){if(!adminEligible.value){resetAI();return}try{const value=await client.settings(library.value);if(closed||g!==generation)return;if(!value.can_admin){resetAI();return}if(!preserve||!settings.value){settings.value=value;settingsDraft.value={ai_enabled:value.ai_enabled,ai_mode:value.ai_mode,auto_new:value.auto_new};settingsDirty.value=false;settingsConflict.value=false}else if(value.revision!==settings.value.revision){settingsConflict.value=true;preview.value=null;aiError.value='AI 设置已变更，当前设置草稿已保留。请重新载入后核对。'}await loadTasks()}catch(e){if(!closed&&g===generation)aiError.value=errorMessage(e)}}
async function loadTasks(){if(!canAdmin.value)return;const g=++taskGeneration,lib=library.value;taskLoading.value=true;clearTimeout(timer);try{const data=await client.tasks(lib,taskStatus.value,taskPage.value);if(closed||g!==taskGeneration||lib!==library.value)return;tasks.value=data.items;taskTotal.value=data.total;taskCounts.value=data.counts;taskSelected.value=taskSelected.value.filter(id=>tasks.value.some(t=>t.id===id&&t.status==='review'));if((data.counts.pending??0)+(data.counts.running??0)>0)timer=setTimeout(()=>void loadTasks(),2000)}catch(e){if(!closed&&g===taskGeneration)aiError.value=errorMessage(e)}finally{if(!closed&&g===taskGeneration)taskLoading.value=false}}
async function selectLibrary(){generation++;editor.value=null;deleteTarget.value=null;items.value=[];message.value='';deleted.value=false;resetAI();await Promise.all([loadCategories(),loadSettings()])}
async function init(preserve=false){const g=++generation,previousLibrary=library.value;try{const list=await api.get<{items:LibraryRef[]}>('/libraries');if(closed||g!==generation)return;libraries.value=readableLibraries(list.items);const selected=libraries.value.find(lib=>lib.id===library.value);if(selected)kind.value=selected.content_kind;else library.value=visibleLibraries.value[0]?.id??0;if(previousLibrary!==library.value){resetAI();editor.value=null;deleteTarget.value=null;preserve=false}if(!canManage.value)deleted.value=false;await Promise.all([loadCategories(g),loadSettings(g,preserve)])}catch(e){if(!closed&&g===generation){error.value=errorMessage(e);loading.value=false}}}
function dirty(){settingsDirty.value=true;preview.value=null}
async function saveAI(){if(!canAdmin.value||aiBusy.value||settingsConflict.value||!settings.value)return;const g=generation,lib=library.value;aiBusy.value=true;aiError.value='';try{const value=await client.saveSettings(lib,{...settingsDraft.value,revision:settings.value.revision});if(closed||g!==generation)return;settings.value=value;settingsDraft.value={ai_enabled:value.ai_enabled,ai_mode:value.ai_mode,auto_new:value.auto_new};settingsDirty.value=false;preview.value=null;aiMessage.value='AI 设置已保存';await loadTasks()}catch(e:any){if(!closed&&g===generation){aiError.value=errorMessage(e);if([403,404,409].includes(e?.status))settingsConflict.value=true}}finally{if(!closed)aiBusy.value=false}}
async function previewAI(){if(!canPreview.value||aiBusy.value)return;const g=generation,lib=library.value;aiBusy.value=true;aiError.value='';preview.value=null;try{const data=await client.enqueue({library_id:lib,limit:Number(limit.value),dry_run:true});if(!closed&&g===generation)preview.value=data}catch(e){if(!closed&&g===generation)aiError.value=errorMessage(e)}finally{if(!closed)aiBusy.value=false}}
async function enqueueAI(){if(!canPreview.value||!preview.value?.eligible||aiBusy.value)return;const g=generation,lib=library.value,batchLimit=preview.value.limit;aiBusy.value=true;aiError.value='';try{const data=await client.enqueue({library_id:lib,limit:batchLimit});if(closed||g!==generation)return;aiMessage.value=`已排队 ${data.queued} 本 · 跳过 ${data.skipped} 本`;preview.value=null;await loadTasks()}catch(e){if(!closed&&g===generation)aiError.value=errorMessage(e)}finally{if(!closed)aiBusy.value=false}}
function toggleTask(id:number,checked:boolean){taskSelected.value=taskSelected.value.filter(value=>value!==id);if(checked&&taskSelected.value.length<100)taskSelected.value.push(id)}
async function taskAction(action:'apply'|'reject'|'cancel'|'retry',ids:number[]){if(!canAdmin.value||aiBusy.value||!ids.length)return;const g=generation,lib=library.value;aiBusy.value=true;aiError.value='';reviewConflicts.value=[];
 try{if(action==='apply'||action==='reject'){const data=await client.review(lib,ids,action);if(closed||g!==generation)return;reviewConflicts.value=data.conflicts;const conflicts=new Set(data.conflicts.map(c=>c.id));taskSelected.value=taskSelected.value.filter(id=>!ids.includes(id)||conflicts.has(id));aiMessage.value=`应用 ${data.applied} 条 · 拒绝 ${data.rejected} 条${data.conflicts.length?' · 冲突建议保留待审核':''}`}
 else if(action==='cancel'){const data=await client.cancel(lib,ids);if(closed||g!==generation)return;aiMessage.value=`已取消 ${data.cancelled} 条任务`}
 else{const data=await client.retry(lib,ids);if(closed||g!==generation)return;aiMessage.value=`已重试 ${data.retried} 条 · 跳过 ${data.skipped} 条`}
 await loadTasks();}catch(e){if(!closed&&g===generation)aiError.value=errorMessage(e)}finally{if(!closed)aiBusy.value=false}
}
function taskCategories(task:CategoryTask){const options=categoryOptions(items.value,library.value,kind.value);return task.category_ids.map(id=>options.find(c=>c.id===id)?.path??'分类已变更').join('、')}
function focus(){if(document.visibilityState==='visible')void init(true)}
function escape(e:KeyboardEvent){if(e.key==='Escape'&&!saving.value&&!busy.value){editor.value=null;deleteTarget.value=null}}
watch(()=>state.accessEpoch,()=>void init(true));
watch(()=>[route.query.library,route.query.content_kind],()=>{library.value=Number(route.query.library)||0;kind.value=route.query.content_kind==='comic'?'comic':'book';void init()});
onMounted(()=>{if(!state.user){void router.replace('/login');return}void init();window.addEventListener('focus',focus);window.addEventListener('online',focus);window.addEventListener('keydown',escape)});onBeforeUnmount(()=>{closed=true;generation++;categoryGeneration++;taskGeneration++;clearTimeout(timer);window.removeEventListener('focus',focus);window.removeEventListener('online',focus);window.removeEventListener('keydown',escape)});
</script>
<template><main class="page categories-page">
<RouterLink class="breadcrumb" :to="kind==='comic'?'/comics':'/'">← {{kind==='comic'?'漫画库':'书库'}}</RouterLink>
<div class="page-title"><div><h1>分类</h1><p>按主题整理{{kind==='comic'?'漫画':'图书'}}，支持三级与多选分类。</p></div><div v-if="canManage" class="category-actions"><button :disabled="busy" @click="treeAction('defaults')">初始化推荐分类</button><button class="primary" @click="openEditor()">新建分类</button></div></div>
<div class="category-filters"><label>分类书库<select v-model="library" @change="selectLibrary"><option v-if="!visibleLibraries.length" :value="0">没有可读书库</option><option v-for="lib in visibleLibraries" :key="lib.id" :value="lib.id">{{lib.name}}</option></select></label><label>内容类型<select v-model="kind" @change="library=visibleLibraries[0]?.id??0;selectLibrary()"><option value="book">图书</option><option value="comic">漫画</option></select></label><label v-if="canManage" class="inline"><input v-model="deleted" type="checkbox" @change="loadCategories()">显示已删除分类</label></div>
<p v-if="message" role="status" class="status-banner">{{message}}</p><p v-if="error" role="alert" class="error">{{error}} <button @click="init(true)">重试</button></p><p v-if="loading" role="status">正在读取分类…</p>
<ul v-else-if="options.length" class="category-tree" aria-label="分类树"><li v-for="item in options" :key="item.id" :class="{deleted:item.deleted}" :style="{'--depth':item.depth}"><div class="category-name"><span v-if="item.deleted">{{item.path}}</span><RouterLink v-else :to="assignmentPath(item)">{{item.path}}</RouterLink><small>{{item.book_count}} {{kind==='comic'?'册':'本'}}<template v-if="item.deleted"> · 已删除</template></small></div><div v-if="canManage&&item.can_manage" class="category-actions"><button v-if="item.deleted" :aria-label="'恢复 '+item.name" :disabled="busy" @click="treeAction('restore',item)">恢复</button><template v-else><button :aria-label="'编辑 '+item.name" @click="openEditor(item)">编辑</button><button :aria-label="'删除 '+item.name" :disabled="busy" @click="deleteTarget=item">删除</button></template></div></li></ul>
<section v-else-if="!error" class="empty"><h2>{{deleted?'没有已删除分类':'本库还没有分类'}}</h2><p>{{deleted?'删除的分类会显示在这里，可按需恢复。':canManage?'新建自定义分类，或初始化推荐分类开始整理。':'管理者添加分类后，可在这里按主题浏览。'}}</p></section>
<p v-if="adminEligible&&!settings&&aiError" role="alert" class="error">{{aiError}} <button @click="loadSettings()">重试 AI 设置</button></p>
<section v-if="canAdmin&&settings" class="category-ai" aria-label="AI 分类"><div class="section-heading"><div><h2>AI 分类</h2><p>仅处理本库未分类且未人工锁定的内容。</p></div></div>
<form class="ai-settings" @submit.prevent="saveAI"><label class="inline"><input v-model="settingsDraft.ai_enabled" type="checkbox" :disabled="aiBusy||settingsConflict" @change="dirty">启用 AI 分类</label><label>归类方式<select v-model="settingsDraft.ai_mode" :disabled="aiBusy||settingsConflict" @change="dirty"><option value="review">生成建议，批量审核</option><option value="direct">直接归类</option></select></label><label class="inline"><input v-model="settingsDraft.auto_new" type="checkbox" :disabled="aiBusy||settingsConflict||!settingsDraft.ai_enabled" @change="dirty">新导入自动识别</label><p class="muted">{{settingsDraft.ai_mode==='direct'?'直接归类会应用高可信度结果，低可信度结果仍需审核。':'审核模式先生成建议，管理员应用后才改变内容分类。'}} 新导入识别需单独开启。</p><button class="primary" :disabled="aiBusy||settingsConflict">{{aiBusy?'正在处理…':'保存 AI 设置'}}</button><button v-if="settingsConflict" type="button" :disabled="aiBusy" @click="loadSettings(generation)">重新载入 AI 设置</button></form>
<p v-if="!settings.configured" class="muted">请先在系统设置中配置 AI 服务。</p><p v-if="settingsDirty" class="muted">设置草稿尚未保存，请保存后预览任务。</p><p v-if="aiError" role="alert" class="error">{{aiError}}</p><p v-if="aiMessage" role="status">{{aiMessage}}</p>
<div class="batch-controls"><label>本次数量上限<input v-model.number="limit" type="number" min="1" max="500" :disabled="aiBusy" @input="preview=null"></label><button :disabled="!canPreview||aiBusy" @click="previewAI">预览待归类内容</button></div>
<div v-if="preview" class="ai-preview" role="status"><strong>可归类 {{preview.eligible}} 本 · 跳过 {{preview.skipped}} 本</strong><p>书名、作者、简介会发送至已配置的 AI 服务，并附上本库可选分类；不发送正文、文件路径或账号信息。</p><p>{{preview.mode==='direct'?'本次直接归类，高可信度结果会应用。':'本次生成待审核建议。'}}预览不调用 AI，提交后才开始请求。</p><button class="primary" :disabled="aiBusy||!canPreview||!preview.eligible" @click="enqueueAI">确认提交 {{preview.eligible}} 本</button><button :disabled="aiBusy" @click="preview=null">取消预览</button></div>
<div class="task-heading"><h3>任务与审核</h3><button :disabled="taskLoading" @click="loadTasks">刷新任务</button></div><div class="task-counts"><span v-for="(count,status) in taskCounts" :key="status">{{taskLabels[status]}} {{count}}</span></div>
<div class="task-toolbar"><label>任务状态<select v-model="taskStatus" @change="taskPage=1;taskSelected=[];loadTasks()"><option value="">全部状态</option><option v-for="(name,status) in taskLabels" :key="status" :value="status">{{name}}</option></select></label><button :disabled="aiBusy||!reviewIDs.length" @click="taskAction('apply',reviewIDs)">应用选中建议</button><button :disabled="aiBusy||!reviewIDs.length" @click="taskAction('reject',reviewIDs)">拒绝选中建议</button></div>
<p v-for="conflict in reviewConflicts" :key="conflict.id" class="error">任务 {{conflict.id}}：{{conflict.reason}}</p><p v-if="taskLoading&&!tasks.length" role="status">正在读取任务…</p><ul v-if="tasks.length" class="category-tasks"><li v-for="task in tasks" :key="task.id"><div class="task-title"><input v-if="task.status==='review'" type="checkbox" :aria-label="'选择任务 '+task.title" :checked="taskSelected.includes(task.id)" :disabled="aiBusy||(!taskSelected.includes(task.id)&&taskSelected.length>=100)" @change="toggleTask(task.id,($event.target as HTMLInputElement).checked)"><strong>{{task.title}}</strong><span class="task-status">{{taskLabels[task.status]}}</span></div><p v-if="task.category_ids.length">{{taskCategories(task)}} <span v-if="task.confidence">· 可信度 {{Math.round(task.confidence*100)}}%</span></p><p v-if="task.reason" class="muted">{{task.reason}}</p><p v-if="task.error" class="error">{{task.error}}</p><button v-if="task.status==='pending'||task.status==='running'" :aria-label="'取消 '+task.title" :disabled="aiBusy" @click="taskAction('cancel',[task.id])">取消任务</button><button v-if="task.status==='failed'" :aria-label="'重试 '+task.title" :disabled="aiBusy" @click="taskAction('retry',[task.id])">重试任务</button></li></ul><p v-else-if="!taskLoading" class="muted">还没有任务。预览并提交后，可在这里查看进度和审核建议。</p>
<div v-if="taskTotal>20" class="pagination"><button :disabled="taskPage===1||taskLoading" @click="taskPage--;taskSelected=[];loadTasks()">任务上一页</button><span>{{taskPage}} / {{Math.ceil(taskTotal/20)}}</span><button :disabled="taskPage*20>=taskTotal||taskLoading" @click="taskPage++;taskSelected=[];loadTasks()">任务下一页</button></div></section>
</main>
<div v-if="editor" class="modal-backdrop" @click.self="!saving&&(editor=null)"><section class="sheet category-editor" role="dialog" aria-modal="true" :aria-label="editor==='create'?'新建分类':'编辑分类'"><div class="section-heading"><h2>{{editor==='create'?'新建分类':'编辑分类'}}</h2><button :disabled="saving" @click="editor=null">关闭</button></div><form @submit.prevent="saveCategory"><label>分类名称<input v-model="draft.name" required maxlength="60" :disabled="saving"></label><label>上级分类<select v-model="draft.parent_id" :disabled="saving"><option :value="null">无（顶级分类）</option><option v-for="item in parentOptions" :key="item.id" :value="item.id">{{item.path}}</option></select></label><p class="muted">分类最多三级，上级只能选择本库分类。</p><p v-if="editError" role="alert" class="error">{{editError}}</p><p v-if="editConflict" class="muted">编辑草稿已保留，尚未保存。请关闭后重新打开核对最新版本。</p><button class="primary" :disabled="saving||editConflict||!canManage||!draft.name.trim()">保存分类</button></form></section></div>
<div v-if="deleteTarget" class="modal-backdrop" @click.self="!busy&&(deleteTarget=null)"><section class="sheet category-editor" role="dialog" aria-modal="true" aria-label="删除分类确认"><h2>删除分类</h2><p>删除「{{deleteTarget.name}}」及其活动子分类，书籍和原文件保留。恢复分类可找回尚未重新手动赋值的关系。</p><p v-if="error" role="alert" class="error">{{error}}</p><div class="category-actions"><button :disabled="busy" @click="deleteTarget=null">取消</button><button :disabled="busy||!canManage" @click="treeAction('remove',deleteTarget)">确认删除分类</button></div></section></div>
</template>
